// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(address caller) internal {
        bool callerIsAdmin;
        try c.isAdmin(caller) returns (bool __r) { callerIsAdmin = __r; } catch { return; }
        caller = address(this);
        bool reverted;
        try c.newEmergencyOracle("d") {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (!callerIsAdmin));
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
